let sigN=0;
/* fill(svg): tinta real mascarada pelo trajeto da caneta. Com {pen:true} desenha só o trajeto (traço fino, para tamanhos pequenos). */
function fill(svg,o={}){const[w,h]=SIG.vb;svg.setAttribute("viewBox","0 0 "+w+" "+h);
 if(o.pen){SIG.d.forEach(d=>{const p=document.createElementNS(NS,"path");p.setAttribute("d",d);svg.appendChild(p)});return[...svg.querySelectorAll("path")]}
 const id="sigm"+(++sigN),m=document.createElementNS(NS,"mask");m.id=id;m.setAttribute("maskUnits","userSpaceOnUse");m.setAttribute("x",-60);m.setAttribute("y",-60);m.setAttribute("width",w+120);m.setAttribute("height",h+120);m.setAttribute("class","sig-m");
 const ps=SIG.d.map(d=>{const p=document.createElementNS(NS,"path");p.setAttribute("d",d);p.setAttribute("fill","none");p.setAttribute("stroke","#fff");p.setAttribute("stroke-width",SIG.w);p.setAttribute("stroke-linecap","round");p.setAttribute("stroke-linejoin","round");m.appendChild(p);return p});
 const ink=document.createElementNS(NS,"path");ink.setAttribute("d",SIG.ink);ink.setAttribute("class","sig-ink");ink.setAttribute("fill-rule","evenodd");
 svg.appendChild(m);svg.appendChild(ink);svg._ink=ink;svg._mask=id;return ps}
const mask=(svg,on)=>{on?svg._ink.setAttribute("mask",`url(#${svg._mask})`):svg._ink.removeAttribute("mask")};
const hide=ps=>ps.forEach(p=>{const L=p.getTotalLength();p.style.strokeDasharray=L+" "+(L+2);p.style.strokeDashoffset=L});
/* escrita: velocidade constante por traço, pausas entre traços, início e fim suaves */
function write(ps,dur,o={}){const L=ps.map(p=>p.getTotalLength()),G=o.gap||46,tot=L.reduce((a,b)=>a+b+G,0)-G;ps.forEach((p,i)=>{p.style.strokeDasharray=L[i]+" "+(L[i]+2);p.style.strokeDashoffset=L[i]});const t0=performance.now();
 (function f(now){const k=cl((now-t0)/1000/dur),s=tot*(.35*k+.65*ES(k));let acc=0,cur=null;ps.forEach((p,i)=>{const d=cl(s-acc,0,L[i]);p.style.strokeDashoffset=L[i]-d;if(d>0&&d<L[i])cur=[p,d,i];acc+=L[i]+G});o.step&&o.step(cur,k,L);if(k<1)requestAnimationFrame(f);else{ps.forEach(p=>{p.style.strokeDasharray="";p.style.strokeDashoffset=""});o.done&&o.done()}})(t0)}
/* escrita disparada pelo scroll (igual ao #sigCard / #sigFt do Plazza) */
const sigWrite=(id,dur=2.6)=>{const s=$(id);if(!s)return;const ps=fill(s);if(matchMedia("(prefers-reduced-motion:reduce)").matches)return;mask(s,1);hide(ps);
 const o=new IntersectionObserver(es=>{if(es[0].isIntersecting){o.disconnect();write(ps,dur,{gap:26,done:()=>mask(s,0)})}},{threshold:.6});o.observe(s)};

/* abertura: a assinatura é escrita no centro e voa até o destino */
function abertura(dest,go){
 const big=$("#sigBig"),sw=$("#sw"),pc=$("#ipc"),bar=$("#ibar"),intro=$("#intro"),ps=fill(big),DUR=3.6;
 const reveal=()=>{dest.style.opacity=1};
 if(matchMedia("(prefers-reduced-motion:reduce)").matches||!intro){intro&&intro.remove();reveal();go();return}
 mask(big,1);hide(ps);let fin=false;
 const toHead=()=>{if(fin)return;fin=true;mask(big,0);sw.style.transition="none";sw.style.transform="none";
  const a=big.getBoundingClientRect(),b=dest.getBoundingClientRect(),s=b.width/a.width;
  big.style.transformOrigin="0 0";big.style.transition="transform 1.5s cubic-bezier(.76,0,.2,1)";big.style.transform=`translate(${b.left-a.left}px,${b.top-a.top}px) scale(${s})`;
  intro.classList.add("out");setTimeout(go,700);
  setTimeout(()=>{reveal();setTimeout(()=>intro.remove(),450)},1500)};
 requestAnimationFrame(()=>requestAnimationFrame(()=>{sw.style.transition=`transform ${DUR+1.6}s cubic-bezier(.25,.1,.2,1)`;sw.style.transform="none"}));
 setTimeout(()=>{if(fin)return;write(ps,DUR,{gap:30,step:(cur,k)=>{pc.textContent=String(Math.round(k*100)).padStart(3,"0");bar.style.transform=`scaleX(${k})`},done:()=>setTimeout(toHead,420)})},380);
 const skip=()=>{ps.forEach(p=>{p.style.strokeDasharray="";p.style.strokeDashoffset=""});toHead()};
 $("#skip").onclick=skip;addEventListener("keydown",e=>{if(e.key==="Escape"&&!fin)skip()})}
